// Products.jsx

import React, { useEffect, useState } from 'react';
import { fetchBooks } from '../api/books';
import { categories } from '../api/categories';
import { useDispatch } from 'react-redux';
import { addToCart } from '../features/cartSlice';
// src/pages/Products.jsx




function Products() {
  const dispatch = useDispatch();
  const [selectedCategory, setSelectedCategory] = useState(categories[0].query);
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function loadBooks() {
      setLoading(true);
      const results = await fetchBooks(selectedCategory);
      setBooks(results);
      setLoading(false);
    }

    loadBooks();
  }, [selectedCategory]);

  const handleAddToCart = book => {
    dispatch(addToCart(book));
  };

  return (
    <div className="products-container">
      <h2>Explore by Category</h2>

      <div className="category-buttons">
        {categories.map(cat => (
          <button
            key={cat.query}
            onClick={() => setSelectedCategory(cat.query)}
            className={selectedCategory === cat.query ? 'active' : ''}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {loading ? (
        <p>Loading books...</p>
      ) : books.length === 0 ? (
        <p>No books found.</p>
      ) : (
        <ul className="book-list">
          {books.map(book => (
            <li key={book.key} className="book-item">
              {book.coverUrl && (
                <img
                  src={book.coverUrl}
                  alt={book.title}
                  className="book-cover"
                />
              )}
              <div className="book-details">
                <h3>{book.title}</h3>
                <p><strong>Author:</strong> {book.author}</p>
                <p><strong>Published:</strong> {book.publishYear}</p>
                <button onClick={() => handleAddToCart(book)}>Add to Cart</button>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

export default Products;
